pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount) public {
        address payable owner = payable(address(uint160(uint256(keccak256(abi.encode(amount))))));
        vm.assume(owner != address(0) && owner != address(c));
        vm.deal(owner, amount);
        vm.prank(owner);
        C c2 = new C();
        // Override smartfix_owner by deploying through owner prank — the constructor sets msg.sender
        // So c2.smartfix_owner() == owner
        vm.prank(owner);
        bool ok;
        try c2.sudicideAnyone{value: amount}() {
            ok = true;
        } catch {
            ok = false;
        }
        // Property: the operation never reverts
        assertTrue(ok);
    }
}

