pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address owner) public {
        vm.assume(owner != address(0));
        // Deploy adversarial helper that will receive the selfdestruct balance
        BalanceReceiver br = new BalanceReceiver();
        // Set the owner to the fuzzed address
        vm.store(address(c), bytes32(uint256(0)), bytes32(uint256(uint160(owner))));
        // Give the owner some ether to pay for gas
        vm.deal(owner, 1 ether);
        vm.prank(owner);
        // Wrap call in try/catch because both selfdestruct and revert may cause call failure
        try c.sudicideAnyone() { } catch { }
        // After the call, the correct contract is destroyed (zero code), buggy one is not.
        // Also check that balance of the receiver is 0 (correct) vs still 0 (buggy) — useless alone.
        // The universal rule: if the owner called sudicideAnyone, code must be gone.
        bool codeZero = address(c).code.length == 0;
        assertTrue(codeZero);
    }
}

