pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount) public {
        vm.assume(amount > 0);
        vm.deal(address(c), amount);
        address owner = c.smartfix_owner();
        vm.prank(owner);
        bool ok = false;
        try c.sudicideAnyone() { ok = true; } catch { ok = false; }
        if (ok) {
            uint256 ownerBalanceAfter = owner.balance;
            assertTrue(ownerBalanceAfter >= address(c).balance + amount);
        } else {
            assertTrue(true);
        }
    }
}

